#    ── ★★ 왜 '단순합'으로 보면 예측이 지는가(수학) ─────────────────────────────────────
#      비중 w ∈ [0,1]이면 Σ(w·r) − Σ(r) = −Σ((1−w)·r)이므로 **빼 둔 날의 수익 합이 음수일 때만**
#      단순합에서 이긴다. 하락을 피해 **복리로 번 것은 단순합에 전혀 반영되지 않는다.**
