#         ★ 이것은 **리스크 파라미터**이므로 **측정만 하고 라이브를 바꾸지 않는다** — 상충을 표로 내고
#           사용자가 고르게 한다. '수익 극대화'와 '위험조정 극대화'는 다른 목표다.
#         ⚠ 한계비율이 **음수**면(CAGR도 내리고 MDD도 나빠짐) "양쪽 다 손해(열등 지배)"로 찍는다 —
#           첫 구현은 그 경우에도 "수익은 오르지만"이라고 써서 틀렸다(테스트가 잡았다).
