#    왜 틀렸는지 뉴스 같은 것도 참고하면서 분석하고 개선해"
#
#    ── 보고서 15 판정: 되돌림 완전 · [리더분산격자] 통과 · [하락경고격자] 실패 ──────
#    (V1 ① 되돌림 완전성 **PASS**) 13f가 보고서13과 비트 동일 — CAGR 0.3704 · MDD −0.1113 · 칼마 3.328
