#      **분산이 수익을 죽인다.** 이득 K=1 +1.17%p → K=2 −0.20%p → K=3 −0.34%p.
#      **수익 전체가 top-1 한 칸에 있다**(편포 때문이다 — 왜도 +0.746). 그래서 분산은 위험만 줄이고
