#        강세             12   +0.32        **0.417**   +14.7
#      ext200(200일선 이격)으로 바꿔도 단조: 약세 +3.91/0.231/+39.4 · 중간 +1.62/0.083/+15.0 ·
#        강세 **−0.75**/**0.417**/+4.4.  m21·m252·dd252 네 지표 모두 같은 방향이다.
