#      (2) 생산자물가 + 유가 $105 돌파로 **9월 연준 인상 확률 ~70%**.
#      기사 표현 그대로 **"가격 추세에 사전 경고가 없었다"**. XME·GDX가 이 시스템의 29산업에 포함되고
#      데이터 마감이 2026-09-11이므로 **이 사건은 표본 안에 있다**.
