#      즉 (가) 저변동성 = 하락의 **사전** 조건, (나) 고변동성·깊은 낙폭 = 하락이 **진행 중**이라는 사실.
#      둘은 서로 다른 도구가 필요하다 — (가)는 경고(R4 진단), (나)는 브레이크(R1 라이브).
