#  VERSION: v0.14.0 - 2026-09-14 - [⚠ 순서기반 채택(리더 0일 해소) · 결합국면 · 17_부모추종조건 · 연도판정]
#    REPORT53. **이 라운드도 산업(I)만 고친다** — S v0.48.0 · M v1.53.1 무수정.
#    사용자 지시: "결과인데 전혀 나아진게 없어 각 산업별로 부모 섹터를 따라가는 경우는 언제이고 반대로
#    움직이는 경우는 언제인지, 어떤 조건인지 파악해서 예측해야돼 그게 왜 안되는건지 원인 찾고 개선방법
#    찾아서 수정해봐". 보고서 12(= v0.13.0 산출) 실측으로 원인 4개를 특정했다.
#
#    ── 원인 진단(보고서 12 실측) ────────────────────────────────────────────────
#    (C1 ★ 치명) **9년 동안 산업 리더가 단 하루도 없었다.** 13l: "총 0회 — 리더가 한 번도 나오지 않았다",
#      채택신호 없음 21,850일 · 국면 게이트 차단 10,445일. 13g 연도별 채택/리더판단사용:
#        2018:1/0  2019:1/0  2020:0/0  2021:1/0  2022:1/0  2023:0/0  2024:0/0  2025:0/0  2026:1/0
#      채택된 5개 연도는 **전부 P_REL_VOL_RATIO 단독**이고 근거는 전부 '최선 가용(t≥1.0, 상위2)'이며,
#      곧바로 "미사용(교차확인 불가 — 사용 신호 1개 < 필요 2개)"로 폐기됐다. 즉 신호를 어떻게 고쳐도
#      **선택이 일어나지 않으니** 사용자가 보는 결과는 변할 수가 없었다. 이것이 "전혀 나아진게 없어"의 절반이다.
#    (C2 ★) **채택 게이트가 크기(t)로 재서 순서 정보를 전부 버린다.** 2018 학습창 13g 실측:
#      순서가 무작위보다 나은 신호 **16/16**(부모안 1위 적중 0.392~0.450 vs 무작위 0.327),
#      |t| ≥ 1.0 인 신호 **4/16**. t가 통과시킨 P_REL_VOL_RATIO는 풀링 상위3−EW29 = −0.071 로
#      **부호가 뒤집힌 신호**다(v0.10.0 H3가 이미 같은 진단을 내렸다 — 그때는 정족수 격자를 퇴역시켰지만
#      정작 고쳐야 할 것은 정족수가 아니라 **채택 잣대**였다). 프로젝트 원칙 재확인:
#      "t는 크기의 진술이지 순서의 진술이 아니다".
#    (C3) **v0.13.0 M상속은 설계대로 작동했으나 산업 고유정보를 0으로 만들었다.** 01_일별 섹터상황 분포가
#      M과 비트 동일(상승 1340 / 중립 618 / 하락 227), conf_notup ≡ m_notup = 0.3867.
#      13p ⑥ ≡ ⑨ 정확히 일치(29산업 MCC 0.0842 · 기술6 0.1147 · SOXX 0.1639), ⑤ ≡ ⑩(0.0634/0.0835).
#      같은 날 29산업 예측의 **단면 상이도 = 0.0000** — 시장 신호 하나를 29번 복사한 것이라
#      "SOXX 같은 기술 산업 하락을 맞춰라"는 구조적으로 답할 수 없다.
#    (C4 ★ 판정 기준 잘못) **v0.13.0의 사전등록 문턱이 풀샘플이었다.** ⑥의 연도별 성적은
#      h=21 정밀도>기저 **4/8년**, h=63 **2/8년**. 풀샘플 MCC 0.0842는 상관 높은 29계열을 6.3만행으로
#      세어 얻은 합성 효과이며, 유효 표본은 '시장 1계열 × 9년'에 가깝다. PASS가 났는데 개선이 없었던 이유다.
#
#    ── 사용자 질문("언제 따라가고 언제 반대로 가는가")에 대한 실측 ───────────────────
#    (M1) 역행(h=21, 부호 불일치) 기저 0.1974. 결합점수 하위20% → 역행 예측:
#         정밀도 **0.2422 vs 기저 0.1997**, 재현율 0.2880, 29산업 중 **21개 MCC>0** —
#         예측일이 산업별로 203~619일로 흩어지는 **산업 고유** 신호다(C3의 0.0000과 대조).
#    (M2 ★ 핵심 구조) 가장 강한 관계는 **M 국면에 따라 부호가 뒤집힌다**:
#         beta63 → 부모초과(rel21) 단면 IC = **+0.0511(M상승아님) / −0.0377(M상승)**, 무조건 평균 −0.0032.
#         volratio도 +0.0309 / −0.0333. 즉 두 국면이 서로를 상쇄해 무조건 평균이 0이 된다.
#         16_산업부모추종은 전이력 고정값이라 이 답을 평균해서 없애버린다 — 사용자 질문의 답이 바로 여기 있었다.
#    (M3) 결합도는 **자기이력 백분위로 재야** 한다: corr63 자기이력 백분위 → fi21 상위3−하위3
#         +0.851%p/21일 **7/8년**, 같은 corr63 원값은 +0.460%p **5/9년**(원값 단면 비교는 GDX 0.42 /
#         KBE 0.93 같은 정적 정체성으로 줄세우는 셈이다 — 16 시트가 정확히 그 형태다).
#    (M4) 엔진이 선택에 쓰는 점수는 부호가 반대다: score_gap → fi21 상위3−하위3 **−1.133%p/21일, 0/9년 양수**,
#         own_score → rel21 −0.645%p **2/9년**. 코드의 사전방향은 이미 SCORE_PCT·SCORE_MINUS_PARENT를
#         −1로 등록해 두었으므로(13g '사전방향 근거') **부호는 고치지 않는다** — 문제는 쓰이지 못한 것(C1)이다.
#
#    ── 이번 변경 ────────────────────────────────────────────────────────────────
#    (P1 ⚠ 기본값 변경 · within_parent_walkforward_select) **ROTATION_ADOPT_BY "t" → "order"**.
#      채택·정렬을 t 대신 **순서여유**(= 13g '학습창 1위=부모안 실현1위 비율' − '무작위 기대')로 하고
#      상위 ROTATION_ORDER_TOP_K(=3)개를 채택한다. 교차확인(ROTATION_MIN_AGREE=2)은 **그대로 둔다** —
#      이제 3개가 채택되므로 정족수가 비로소 성립한다(우연 거르기 목적은 유지, 구조적 불가능만 제거).
#      순서여유는 새로 계산하지 않는다 — 13g가 이미 내던 stats_hit 값을 쓴다(C2의 잣대를 그대로 채택에 연결).
#      시뮬레이션 실측(r53 pf8, 워크포워드·사전등록 부호 고정):
#        리더일 **0 → 연 888~1,831일**, 부모안 적중 **0.378 vs 무작위 0.343 — 8/8년 무작위 초과**,
#        리더 21일 부모초과 **+0.209%** vs 타산업 **−0.120%**(차이 +0.329%p, 5/8년 양수).
#      ⚠ 판정 잣대는 **순서(적중>무작위)**다 — 수익 차이는 5/8년이므로 수익으로 판정하지 않는다(C4 교훈).
#      ⚠ 되돌리기: i_overrides={"ROTATION_ADOPT_BY": "t"}
#    (P2 신규 · build_coupling_state) **결합국면** — 산업↔부모 결합도를 인과·시변 상태로 만든다.
#      결합점수 = mean(corr63 자기이력백분위, 1−idio_share 자기이력백분위, pvol21 자기이력백분위),
#      하위 COUPLING_LO(1/3) = 탈동조 · 상위 COUPLING_HI(2/3) = 강결합 · 사이 = 보통.
#      01_일별에 '결합점수백분위'·'결합국면' 2열 추가. 근거 M1·M3. 되돌리기: i_overrides={"COUPLING_STATE": False}
#    (P3 신규 시트 17_부모추종조건 · build_parent_follow_conditions) 사용자 질문에 직접 답하는 시트.
#      블록 A 결합국면 × M국면 조건부 추종/역행률(h=5/21/63) · 블록 B 산업별 역행 소수클래스
#      (정밀도/재현율/균형/MCC + **연도 정밀도>기저 k/n**) · 블록 C 부호반전표(M상승 vs M상승아님에서
#      beta63·volratio·corr63의 단면 IC) · 블록 D 해석. 기저(역행률)를 같은 행에 함께 실어 판정 가능하게 한다.
#    (P4 ★ 판정 기준 변경) **연도별 부호일치를 1급 기준으로.** _down_metrics_yearly 추가 →
#      13p 블록 A2 각 규칙 행에 '연도 정밀도>기저'(k/n)와 '연도 MCC>0'(k/n) 열을 싣고,
#      00_실행요약의 국면 판정이 **풀샘플 MCC가 아니라 연도 k/n**을 보고 판정하게 바꾼다.
#      v0.13.0 ⑥이 풀샘플 문턱을 전부 통과했는데도(29 MCC 0.0842≥0.06, 기술6 0.1147≥0.09, SOXX 0.1639≥0.12,
#      재현율 0.4338≥0.35, 균형 0.5414>0.53) 사용자에게 개선으로 보이지 않은 원인이 C4이므로,
#      같은 실수가 반복되지 않게 판정 자체를 고친다. 이번 P1·P2·P3의 사전등록 문턱도 전부 연도 k/n이다.
#    (P5 · build_parent_following_analysis) 16_산업부모추종 **정직화** — 전이력 베타·상관·추종률 열 머리에
#      '정적(예측불가)' 표시를 달고, 자기이력 백분위 기반 열(결합국면 분포·국면별 조건부 초과)을 추가한다.
#      M3 근거: 원값 단면 비교는 5/9년, 자기이력 백분위는 7/8년.
#
#    [검증] 이번 라운드 사전등록 문턱(전부 **연도 k/n** 기준, 다음 실행에서 판정):
#      P1 ① 13l 리더일 > 0 인 연도 ≥ 7/9  ② 13l '리더=부모안 실현1위' > 무작위 인 연도 ≥ 7/9
#         ③ 13g 연도별 '리더 판단 사용' ≥ 2 인 연도 ≥ 7/9   ④ I★ CAGR·MDD는 판정에 쓰지 않는다
#      P2 ⑤ 17 블록 A 에서 탈동조 구간 역행률 > 강결합 구간 역행률 인 연도 ≥ 6/8
#      P3 ⑥ 17 블록 B 29산업 평균 역행 정밀도 > 기저 인 연도 ≥ 5/8  ⑦ MCC>0 산업 ≥ 18/29
#      P4 ⑧ 13p 블록 A2 ⑥의 '연도 정밀도>기저'가 4/8로 보고되는지 확인(= C4 재현 — 보고서 12와 일치해야 한다)
#    ⚠ 이것은 연구·교육용 도구이며 투자 조언이 아니다. 위험 파라미터(포지션 크기·손절)는 이번에 건드리지 않았다.
#    ⚠ INDUSTRY_SLEEVE_SHARE(0.0) · INDUSTRY_LEADER_STANDALONE_EDGE(None)는 그대로 둔다 —
#      후자는 v0.10.0 H3에서 이미 실패 판정(−0.36/−0.37%p)이며 P1이 그 문제를 정면으로 대체한다.
#
#  VERSION: v0.13.0 - 2026-09-14 - [배분 시트 상시 산출 · ⚠ 산업 국면을 M 상속으로 · 국면 라벨 비교 블록]
#    REPORT52 §5 E1·S1~S3·§6 N1~N6. **이 라운드는 산업(I)만 고친다**(사용자 지시 "industry만 수정")
#    — S v0.48.0 · M v1.53.1은 손대지 않았다. 아래 함수/라인 참조는 이 파일의 현재 버전 기준.
#
#    (N1 ⚠ 기본값 변경 · 사용자 지시 — REPORT52 §1·§5 E1) INDUSTRY_LAYER_FROZEN **True → False**, 그리고
#      **동결이 더 이상 배분 시트를 지우지 않는다.** v0.12.0의 경로 A(동결)가 13_산업배분전략(전략별 수익)·
#      13b·13c_일별배분비중·13c2·13f·13j·13l·14·15를 통째로 없앴고 사용자가 "왜 산업 전략별 수익, 일별배분
#      비중 시트 또 없앴어? 다시 생기게 해"라고 지적했다(R46 R6에 이어 **두 번째**). 구조를 고친다:
#        · 기본값 False(해제) — 배분·격자·수용기준 전부 산출.
#        · 동결(True)이어도 run()이 build_industry_allocation을 **격자만 꺼서** 호출한다
#          (`_frozen_alloc_cfg()` 신설 — INDUSTRY_GRID=False + 이름이 `_GRID`로 끝나는 모든 필드를 ()로
#          replace). 그래서 13·13b·13c·13c2·14는 ★·대조군A/B·S★재현 4행 기준으로 **항상** 나오고,
#          생략되는 것은 격자 행과 13f(수용기준)·13j(거래내역)·13l(리더적중률)·15(귀속)뿐이다.
#        · 규약에 고정: "동결로 13·13c를 없애지 않는다"(HANDOFF §4-10). 시간 절약(≈40분)은 격자에서 온다.
#      변경 함수: IndustryConfig.INDUSTRY_LAYER_FROZEN(기본값·주석) · _frozen_alloc_cfg(신설) ·
#        run(alloc 호출·13f/13j/13l/15 게이트) · build_industry_report(_frozen 게이트·00시트 생략 목록 문구).
#      ⚠ 되돌리기(동결 복귀, 격자·13f·13j·13l·15만 생략): i_overrides={"INDUSTRY_LAYER_FROZEN": True}
#
#    (N2 ⚠⚠ 신호층 기본값 변경 — 이번 라운드의 유일한 ⚠, REPORT52 §2~4·§6 N2) 산업 확정국면·목표비중을
#      **M(SPY) 국면 상속**으로 바꾼다. INDUSTRY_REGIME_SOURCE 신설(기본 "m_inherit").
#      왜(원자료 23규칙 실측, REPORT52 §4 — 전부 2018-01-02~, 29산업, h=21 소수클래스 MCC):
#        · 산업 **자기** 기계의 하락 라벨 = 0.007(29평균) / 0.057(기술6) / 0.060(SOXX) — 정보 없음.
#          13p 실측으로는 29평균 **0.004** · 재현율 0.130(실현 하락의 87%를 '상승/중립'이라 했다).
#          2022년에는 29산업 중 25개가 하락 예측 정밀도 < 기저율(= 떨어진 뒤에 하락이라 했다),
#          2024년(SOXX −25%)에는 16개 산업이 하락 예측 **0일**, SOXX는 급락 중 자기 점수 백분위가
#          0.30 → 0.93으로 **역행**하며 목표비중이 0.4 → 1.0으로 늘었다.
#        · 원인은 신호가 아니라 구조다: 산업 복합점수의 채택 지표가 대부분 매크로(SOXX PASS 21개 중 19개,
#          17개가 63일 지평 금리·물가·달러·신용)라 산업 고유 하락에 무감각하고 금리 하락기의 기술주 급락
#          에는 역행한다. 위험(H)·급락트리거는 이미 SPY 것을 공유하므로 자기 고유 정보는 점수 문턱뿐이다.
#        · **M 상승 아님(중립∪하락)** = 0.075 / 0.106 / SOXX 0.154(정밀 0.477·재현 0.482·균형 0.537,
#          29산업 중 27개 양수) — 유일하게 재현율과 MCC를 동시에 갖는다. 자기 점수·자기 H·부모 H·
#          200/50/20일선·모멘텀·낙폭·변동성 급등·형제산업 폭·급락트리거는 전부 무작위 이하이고, M과의
#          & / | 조합도 M 단독을 넘지 못한다. h=63에서는 어느 규칙도 정보가 없다.
#        · ⚠ **M의 '하락' 라벨만 상속하면 −0.004로 정보가 없다** — 정보는 '상승 아님'에 있다. 그래서
#          M 중립일을 산업에서도 **중립(목표 0.5)**으로 상속하고, 판정은 '상승 아님' 기준으로 낸다
#          (M 자신을 13p에서 '현금 기준'·'상승아님 기준'으로 재는 이 프로젝트의 기존 관행과 같다).
#      무엇을 바꿨나(run_industry, generate_signals 직후 한 곳):
#        · state = M 확정국면(RISK_ON/NEUTRAL/RISK_OFF)을 산업 거래일로 reindex+ffill,
#          target_pos = M 목표비중(중립 0.5·규칙 ⑨ 감축 0.0 포함) 그대로. 라벨과 비중이 **같은 출처**라
#          "현금이라 적고 보유" 모순이 생기지 않는다(v0.15.0 §A 교훈).
#        · 자기 기계 값은 **버리지 않는다** — results["own_state"]/["own_target_pos"]로 보존하고
#          01_일별_<산업>에 '자기국면'·'자기 목표비중'·'국면 소스' 3열을 덧붙인다(13p 블록 A2가 이 값으로
#          매 실행 자기 vs 상속을 비교한다). 자기 복합점수·H·추세·규칙 발동 열은 전부 그대로 남는다
#          (그 열들은 이제 '자기국면'의 근거이며 확정국면의 근거가 아니다 — 00시트에 명시).
#        · 산업 순환매(13g 채택·리더)·슬리브·rot_raw는 **무관**(그 계산은 점수·가격에서 나온다). 적격
#          판정(state=="RISK_ON")은 이제 M 상승일과 같아진다 — 리더는 여전히 교차확인(채택 0~1개)으로
#          구조적 불가라 산업 배분 0일·**I★ ≡ S★**가 유지된다(14_계층정합이 매일 검사).
#      사전등록(기본 꺼짐) — "m_inherit_own_down": M 상속 + **자기 기계가 하락이라 한 날은 하락 유지**
#        (목표비중은 min(M, 자기)). 같은 실측에서 0.072 / 0.105 / 0.154로 순수 상속과 사실상 동률이고
#        산업별 차이를 남긴다 — 다음 실행의 13p 블록 A2가 두 규칙을 같은 표에서 판정한 뒤 고른다.
#        참고로 '자기 상승아님 ∪ M 상승아님'은 0.062 / 0.090 / 0.119로 **더 나빠서** 넣지 않았다
#        (자기 중립일이 희석한다 — 이 라운드에서 새로 측정).
#      ⚠ 되돌리기(v0.12.0 동작): i_overrides={"INDUSTRY_REGIME_SOURCE": "own"}
#      사전 고정 판정(REPORT52 §6 N2, 다음 실행 13p 블록 A·A2 h=21): 29평균 MCC ≥ 0.06 · 기술6 ≥ 0.09 ·
#        SOXX ≥ 0.12 · 재현율 ≥ 0.35 · 균형정확도 > 0.53. 미달이면 "own"으로 되돌리고 원인을 적는다.
#
#    (N3 ★ 신규 진단 — REPORT52 §5 E2·§6 N3) 13p에 **블록 A2 '국면 라벨 비교(하락 경고)'** 신설
#      (build_industry_regime_label_block). 산업별 × 규칙 6종(자기 라벨 / 자기 현금 / 자기 상승아님 /
#      확정 상승아님(=이번 라운드 규칙) / 자기하락 ∪ M상승아님(사전등록) / 부모 상승아님) × (예측일·정밀도·
#      재현율·균형정확도·MCC) + '── 29산업 평균 ──'·'── 기술 6종 평균 ──' 행, h=21·h=5. 종전에는 산업 13p가
#      S.build_minority_class_accuracy(alloc=None)만 써서 'M상속' 열이 전부 비어 있었고(그 함수는 alloc에서
#      M 계열을 꺼낸다) 이번 판독을 시트만으로는 할 수 없었다 — run()이 이제 M 국면·목표비중을 그 함수에
#      **합성 dict로 넘겨** 블록 A의 'M상속(M현금/M상승아님) 정밀도·균형정확도·MCC'·'M상속 우위(MCC차)'
#      열도 채운다(S 코드는 손대지 않았다 — 인자만 채운다).
#    (N4 ★ 신규 진단 — REPORT52 §6 N4) 같은 블록에 **연도별 요약 행** — 연도 × (29산업 하락 예측일 합·
#      하락 예측 0일 산업 수·정밀도 < 기저 산업 수). "2024년 16개 산업 0일"·"2022년 25/29가 늦었다"를
#      매 실행 감시한다(REPORT52 §2.2의 표를 시트로).
#    (N6 문서) 위 근거를 이 CHANGELOG와 00시트에 남긴다. run_pipeline은 v1.9.0으로 레시피·되돌리기 갱신.
#      REPORT52 §5 S3 — 산업 **고유** 조정(2024-07 반도체형)은 현재 후보군으로 21일 앞서 예측되지 않는다:
#      시험해 닫은 23규칙을 HANDOFF §10 닫힌 방향에 등록했다(외부 데이터 없이는 다시 열지 않는다).
#    (N5 보류) 슬리브 경로 B(INDUSTRY_SLEEVE_ADOPT_BY="hit")는 이번 라운드에 넣지 않는다 — N2가 유일한
#      신호층 변경이어야 판정이 섞이지 않는다(REPORT52 §6 N5). 슬리브 격자·대조 2행은 N1로 13 시트가
#      돌아오면서 v0.11.0과 같은 모습으로 다시 나온다(HAZ_PCT_OWN 채택, 기대치는 REPORT51 §3.1 그대로).
#
#    [검증] 이 세션에는 실제 시장데이터·M 모듈 실행 경로·정식 회귀 스위트(test_industry_v0*.py)가 없다.
#    한 것: (1) py_compile·ast.parse 통과 (2) N2 상속 로직·N3/N4 블록을 합성데이터로 자체 단위테스트
#    (scratch — M 중립일이 산업 중립·목표 0.5로, M 하락일이 하락·0.0으로 상속되고, 자기 값이 own_state로
#    보존되며, 블록 A2의 MCC·정밀·재현이 수기 계산과 1e-12 이내 일치, "own"이면 v0.12.0과 동일 출력)
#    (3) N1의 _frozen_alloc_cfg가 `_GRID` 6종 + INDUSTRY_GRID를 모두 끄는지 dataclasses.fields로 확인.
#    **로컬에서 반드시 필요한 것**: REPORT52 §7 표 7항목 실측(특히 13p A2 29평균 MCC ≥ 0.06·SOXX ≥ 0.12,
#    13·13c 시트 존재, 14 위반 0일, I★ = S★ 비트 동일), 회귀 스위트 전종 재실행 + 기본값 가드 갱신
#    (INDUSTRY_LAYER_FROZEN=False·INDUSTRY_REGIME_SOURCE="m_inherit"), test_industry_v07_minority에
#    블록 A2 존재·'own' 되돌리기 동등성 테스트 추가.
#
#  VERSION: v0.12.0 - 2026-09-14 - [중복 후보 제거·블록 P 분모 수정·CHANGELOG 정정·순환매신호 감사 신설·
#    산업 계층 재동결] REPORT51 §4 E1~E3·§5 M1~M3+경로A·§7. 아래 함수/라인 참조는 이 파일의 현재 버전 기준.
#
#    (M1 ⚠ 결함수정 — REPORT51 §3.4 E1) ABS_MOM_12_1을 INDUSTRY_POOLED_ONLY_SIGNALS에서 제거. 12-1 절대
#      모멘텀은 모든 산업에 같은 SPY 계수를 더한 것뿐이라 S_REL_MOM_12_1과 횡단면 순위가 완전히 동치다
#      (13g 9개 학습창의 t·적중·n이 소수점까지 일치) — 실질 후보 7종이 아니라 6종이었고, 사실상 같은 신호에
#      투표가 두 번 실릴 여지가 있었다. ABS_MOM_12_1 자체 계산(rot_raw, run_industry)은 그대로 둔다 —
#      제거는 _pool_universe/13g 풀링 진단/슬리브 채택 자격에서만이다(K2가 등록한 명단에서 한 줄 삭제,
#      새 산식 없음). 되돌리기: IndustryConfig(INDUSTRY_POOLED_ONLY_SIGNALS=(..., "ABS_MOM_12_1")).
#    (M2 ⚠ 결함수정 — REPORT51 §3.4 E3) 13p 블록 P '최빈 부모 몫'의 분모가 전체 평가일수(_n_eval 격)였다
#      (`_sf[c].mean()`는 암묵적으로 전체일로 나눈다) — 라벨은 "형성일 기준"인데 산식은 전체일 기준이라
#      형성 1,177일 기준으로 읽으면 표시값의 ≈1.9배(≈8.6%→≈16%)였다. 분모를 형성일수(`_n_form`)로 고쳤다
#      (`build_industry_allocation`의 `_top_parent_by_k[_k_]` 계산 블록, `_parent_hold[_p_] += _sf[c_].sum() /
#      max(_n_form, 1)`). 이번 판정(쏠림 없음)의 결론 자체는 바뀌지 않는다 — 라벨과 산식을 일치시키는
#      표시 수정이며 배분·채택에는 영향이 없다.
#    (M3 문서 정정 — REPORT51 §3.4 E2) v0.11.0 CHANGELOG(K2)의 "rot_raw가 11_룩어헤드감사 절단재계산
#      대상에도 자동 등록된다"는 기재가 사실이 아니었다는 정정을 K2 항목 본문에 직접 추가했다(아래, 원문은
#      보존). 실제로는 복합점수·위험점수(H) 두 값만 절단재계산됐다 — 그 공백을 아래 L6이 메운다.
#    (L6 ★ 신규 시트 — REPORT51 §5 L6, sector_rotation.py L6과 같은 방법론) 11_룩어헤드감사가 검증하지
#      않던 rot_raw 원시신호(P_REL_*·S_REL_*·ABS_MOM_12_1·REL_RET·REL_RET_BN·PARENT_BETA_252 등)를 절단
#      재계산으로 검증한다. 신규 시트 11b_순환매신호감사. run_industry()의 인라인 rot_raw 블록을 먼저
#      build_industry_rotation_raw_signals()로 추출했다(산식 변경 없음, 비트 동일 — 순수 리팩터). 이 함수의
#      **직접 입력**(ind_i·adj_i·parent_tr·parent_series·score_pct_full·haz_pct_industry_full)만 무작위
#      검사일 d까지 잘라 재호출하고 d 시점 값을 비교하는 industry_rotation_raw_lookahead_audit()이 감사
#      본체다(ind_i 자체의 인과성은 기존 industry_lookahead_audit이 이미 검증하므로 중복 검사하지 않는다 —
#      S 쪽과 같은 범위 설계). sector_rotation.py의 rotation_raw_lookahead_audit()을 그대로 재사용하지는
#      "못했다" — 산업 rot_raw는 run_industry() 안에 인라인이라 시그니처가 달라(score/adj_i/spy_tr/haz_score
#      직접 인자가 아니라 ind_i·parent_tr·parent_series·score_pct_full/haz_pct_industry_full) 쌍둥이 함수를
#      새로 썼다(S 파일 v0.48.0 L6 changelog에도 이 정정을 남겼다). 변경 함수: run_industry(호출·rot_audit
#      반환) · run(rot_audit 취합) · build_industry_report(11b 시트·00시트 1줄 "순환매신호 감사(L6)").
#      RUN_LOOKAHEAD_AUDIT·AUDIT_SAMPLE 재사용(신규 설정 없음).
#    (경로 A ⚠ 기본값 변경 — REPORT51 §7, 사용자 위임 후 내 선택) INDUSTRY_LAYER_FROZEN False → **True**
#      (재동결). REPORT51 §3.1의 사전 등록 K7 문턱 둘 다 미달(①순서·크기를 동시에 가진 후보 없음 ②슬리브가
#      대조군과 구별 불가)이었다 — 사전 고정 규칙대로면 이 결과는 No-Go(경로 A)다. 보고서가 권고한 경로
#      B(사후 규칙 변경으로 게이트를 순서 우선으로 바꿔 한 번 더 시도)는 시뮬레이션조차 ★를 넘지 못했고
#      (§3.3-c) 보고서 스스로 "성과 개선이 아니라 순서 정보의 존재를 기록하는 것"이라 적었다 — 사전 등록
#      원칙(격자를 본 뒤 문턱을 바꾸지 않는다)을 깨면서까지 택할 값어치가 아니라고 판단했다. 상세 근거는
#      IndustryConfig.INDUSTRY_LAYER_FROZEN 필드 주석(아래) 참조. 동결이어도 13g·13p·16 등 진단 시트는
#      그대로 나온다 — 생략되는 것은 배분·격자·수용기준뿐이다(v0.5.0 I-A와 같은 관행).
#      ⚠ 되돌리기: i_overrides={"INDUSTRY_LAYER_FROZEN": False}
