#    raw_signals()의 출력 열 26개가 전부 채워지고 ABS_MOM_12_1/REL_RET/SCORE_MINUS_PARENT가 수기 재유도값과
#    1e-12 이내로 일치, (2) 인과적(룩어헤드 없는) 합성 입력에서 절단재계산 156건 중 불일치·오류 0건,
#    (3) 한 열에 의도적으로 미래 정보를 주입하면 감사가 정확히 그 열·그 날짜를 "불일치"로 검출. ast.parse·
