    #     기존 폴백은 '적격(=상승)' 바스켓이라 서로 다른 집합이다.
    INDUSTRY_NEUTRAL_BASKET_GRID: Tuple[float, ...] = (0.25, 0.5)
    #   분산게이트: 부모 안 63일 상대수익 횡단면 σ가 롤링 252일 상위 q분위일 때만 리더 인정(§3.4 H3).
    INDUSTRY_DISPERSION_GATE_GRID: Tuple[float, ...] = (0.5, 0.75)
